begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(36);
select is((select n.nspname from pg_extension e join pg_namespace n on n.oid=e.extnamespace where e.extname='vector'),'extensions','pgvector no schema extensions');
select has_column('public','erp_catalog_items',column_name,format('coluna %s existe',column_name))from unnest(array['embedding','embedding_model','embedding_content_hash','embedding_updated_at','fts'])names(column_name);
select ok(to_regclass('public.erp_catalog_items_embedding_idx')is not null,'índice HNSW existe');select ok(to_regclass('public.erp_catalog_items_fts_idx')is not null,'índice GIN existe');
select ok(exists(select 1 from pg_constraint where conname='erp_catalog_embedding_metadata_valid'),'metadados vetoriais são coerentes');
select ok(to_regprocedure('public.match_catalog_hybrid(extensions.vector,text,uuid,integer)')is not null,'RPC híbrida existe');
select ok(not(select prosecdef from pg_proc where oid='public.match_catalog_hybrid(extensions.vector,text,uuid,integer)'::regprocedure),'RPC usa security invoker');
select ok(not has_function_privilege('anon','public.match_catalog_hybrid(extensions.vector,text,uuid,integer)','EXECUTE'),'anon não pesquisa');select ok(has_function_privilege('authenticated','public.match_catalog_hybrid(extensions.vector,text,uuid,integer)','EXECUTE'),'authenticated pesquisa sob RLS');
select ok(pg_get_functiondef('public.match_catalog_hybrid(extensions.vector,text,uuid,integer)'::regprocedure)like '%has_permission%','RPC exige permissão de catálogo');
select ok(pg_get_functiondef('public.match_catalog_hybrid(extensions.vector,text,uuid,integer)'::regprocedure)like '%BETWEEN 1 AND 50%','RPC limita quantidade');
select ok(pg_get_functiondef('public.match_catalog_hybrid(extensions.vector,text,uuid,integer)'::regprocedure)~'60\s*\+','RPC usa RRF determinístico');
select ok((select indexdef like '%WHERE (embedding IS NOT NULL)%'from pg_indexes where schemaname='public'and indexname='erp_catalog_items_embedding_idx'),'HNSW ignora embedding nulo');
select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding','INSERT'),'cliente não insere vetor');select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding','UPDATE'),'cliente não atualiza vetor');
select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_model','INSERT'),'cliente não insere modelo');select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_model','UPDATE'),'cliente não atualiza modelo');
select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_content_hash','INSERT'),'cliente não insere hash');select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_content_hash','UPDATE'),'cliente não atualiza hash');
select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_updated_at','INSERT'),'cliente não insere data vetorial');select ok(not has_column_privilege('authenticated','public.erp_catalog_items','embedding_updated_at','UPDATE'),'cliente não atualiza data vetorial');
select ok(has_column_privilege('authenticated','public.erp_catalog_items','name','INSERT'),'cliente pode inserir nome sob RLS');select ok(has_column_privilege('authenticated','public.erp_catalog_items','name','UPDATE'),'cliente pode atualizar nome sob RLS');select ok(has_column_privilege('authenticated','public.erp_catalog_items','description','INSERT'),'cliente pode inserir descrição sob RLS');select ok(has_column_privilege('authenticated','public.erp_catalog_items','description','UPDATE'),'cliente pode atualizar descrição sob RLS');
select ok((select relrowsecurity from pg_class where oid='public.erp_catalog_items'::regclass),'RLS permanece ativa');select ok(has_table_privilege('authenticated','public.erp_catalog_items','SELECT'),'authenticated lê catálogo sob RLS');select ok(not has_table_privilege('anon','public.erp_catalog_items','SELECT'),'anon não lê catálogo');
select is((select is_generated from information_schema.columns where table_schema='public'and table_name='erp_catalog_items'and column_name='fts'),'ALWAYS','FTS é gerado');
select ok(exists(select 1 from pg_constraint where conrelid='public.erp_catalog_items'::regclass and conname='erp_catalog_embedding_metadata_valid'),'constraint vetorial pertence ao catálogo');
select is((select count(*)::integer from public.erp_catalog_items where embedding is not null),0,'zero embeddings reais/fictícios');
select ok(pg_get_functiondef('public.match_catalog_hybrid(extensions.vector,text,uuid,integer)'::regprocedure)like '%query_embedding IS NULL%','fallback lexical aceita vetor nulo');
select * from finish();rollback;
